package app.y700.proc;
final class Scripts {
    static final String SAMPLE = "#!/system/bin/sh\n# 采样一次 CPU 和内存，输出一行 JSON。参数 loop 时每 2 秒一次。\n# 不用 toybox tr。toybox 的 tr '\\0' 会空转占满一核。\nBB=/data/adb/magisk/busybox\nDIR=/data/adb/y700-proc\nLOG=$DIR/proc.log\nmkdir -p \"$DIR\"\n\nrun_once() {\n  \"$BB\" awk -v bb=\"$BB\" '\nfunction ncpu(   n, line) {\n  n = 0\n  while ((getline line < \"/proc/stat\") > 0)\n    if (line ~ /^cpu[0-9]/) n++\n  close(\"/proc/stat\")\n  return n < 1 ? 1 : n\n}\nfunction cpu_pair(   line, n, i, s, idle) {\n  s = 0\n  idle = 0\n  while ((getline line < \"/proc/stat\") > 0) {\n    if (line ~ /^cpu /) {\n      n = split(line, f, \" \")\n      for (i = 2; i <= 8 && i <= n; i++) s += f[i]\n      idle = f[5] + 0\n      if (n >= 6) idle += f[6]\n      break\n    }\n  }\n  close(\"/proc/stat\")\n  cpu_total = s\n  cpu_idle = idle\n}\nfunction meminfo(   line, mf) {\n  mem_total = 0\n  mem_avail = 0\n  swap_total = 0\n  swap_free = 0\n  while ((getline line < \"/proc/meminfo\") > 0) {\n    split(line, mf, /[ :]+/)\n    if (mf[1] == \"MemTotal\") mem_total = mf[2] + 0\n    else if (mf[1] == \"MemAvailable\") mem_avail = mf[2] + 0\n    else if (mf[1] == \"SwapTotal\") swap_total = mf[2] + 0\n    else if (mf[1] == \"SwapFree\") swap_free = mf[2] + 0\n  }\n  close(\"/proc/meminfo\")\n}\nfunction collect(slot,   cmd, line, pid, sl, name, uid, rss, st, m, rest, nf, ticks) {\n  cmd = \"ls -d /proc/[0-9]*\"\n  while ((cmd | getline line) > 0) {\n    pid = line\n    sub(/^.*\\//, \"\", pid)\n    name = \"\"\n    uid = -1\n    rss = 0\n    while ((getline sl < (\"/proc/\" pid \"/status\")) > 0) {\n      if (sl ~ /^Name:/) {\n        name = sl\n        sub(/^Name:[ \\t]*/, \"\", name)\n      } else if (sl ~ /^Uid:/) {\n        split(sl, uf, /[ \\t]+/)\n        uid = uf[2] + 0\n      } else if (sl ~ /^VmRSS:/) {\n        split(sl, rf, /[ \\t]+/)\n        rss = rf[2] + 0\n      }\n    }\n    close(\"/proc/\" pid \"/status\")\n    ticks = 0\n    st = \"\"\n    if ((getline st < (\"/proc/\" pid \"/stat\")) > 0) {\n      m = match(st, /\\) /)\n      if (m > 0) {\n        rest = substr(st, m + RLENGTH)\n        nf = split(rest, ff, \" \")\n        if (nf >= 13) ticks = ff[12] + ff[13]\n      }\n    }\n    close(\"/proc/\" pid \"/stat\")\n    if (slot == 1) {\n      ta[pid] = ticks\n      ra[pid] = rss\n      ua[pid] = uid\n      na[pid] = name\n    } else {\n      tb[pid] = ticks\n    }\n  }\n  close(cmd)\n}\nfunction esc(s) {\n  gsub(/\\\\/, \"\", s)\n  gsub(/\"/, \"\", s)\n  gsub(/[\\n\\r\\t]/, \" \", s)\n  return s\n}\nfunction emit(   dt, di, busy, one, pid, dlt, pct, uid, rss, name, key) {\n  dt = cpu_total - base_total\n  di = cpu_idle - base_idle\n  if (dt < 1) dt = 1\n  busy = (dt - di) * 100 / dt\n  if (busy < 0) busy = 0\n  if (busy > 100) busy = 100\n  one = dt / nc\n  if (one < 1) one = 1\n  delete seen\n  for (pid in tb) {\n    dlt = tb[pid] - ta[pid]\n    if (dlt < 0) dlt = 0\n    pct = dlt * 100 / one\n    uid = ua[pid] + 0\n    if (ua[pid] == \"\") continue\n    rss = ra[pid] + 0\n    name = na[pid]\n    if (rss < 20000 && pct < 1) continue\n    if (uid >= 10000) key = \"u\" uid\n    else key = \"p\" pid\n    if (!(key in seen)) {\n      seen[key] = 1\n      krss[key] = 0\n      kcpu[key] = 0\n      kn[key] = 0\n      kuid[key] = uid\n      kpid[key] = pid\n      kname[key] = name\n    }\n    krss[key] += rss\n    kcpu[key] += pct\n    kn[key]++\n    if (rss >= krss_top[key]) {\n      krss_top[key] = rss\n      kname[key] = name\n      kpid[key] = pid\n    }\n  }\n  items = \"\"\n  nitem = 0\n  top_mem_name = \"\"\n  top_mem = 0\n  top_cpu_name = \"\"\n  top_cpu = 0\n  for (key in seen) {\n    if (nitem >= 80) break\n    if (nitem > 0) items = items \",\"\n    nitem++\n    name = esc(kname[key])\n    items = items sprintf(\"{\\\"key\\\":\\\"%s\\\",\\\"uid\\\":%d,\\\"pid\\\":%d,\\\"name\\\":\\\"%s\\\",\\\"rss\\\":%d,\\\"cpu\\\":%.1f,\\\"n\\\":%d}\", key, kuid[key], kpid[key], name, krss[key], kcpu[key], kn[key])\n    if (krss[key] > top_mem) { top_mem = krss[key]; top_mem_name = name }\n    if (kcpu[key] > top_cpu) { top_cpu = kcpu[key]; top_cpu_name = name }\n  }\n  meminfo()\n  printf \"{\\\"ok\\\":true,\\\"mem_total\\\":%d,\\\"mem_avail\\\":%d,\\\"swap_used\\\":%d,\\\"cpu\\\":%.1f,\\\"ncpu\\\":%d,\\\"items\\\":[%s]}\\n\", mem_total, mem_avail, (swap_total - swap_free), busy, nc, items\n  fflush()\n  cmd = bb \" date +%Y-%m-%dT%H:%M:%S\"\n  stamp = \"\"\n  if ((cmd | getline stamp) > 0) { }\n  close(cmd)\n  msg = stamp \" avail=\" int(mem_avail / 1024) \"MB cpu=\" sprintf(\"%.1f\", busy) \"% top_mem=\" top_mem_name \" \" int(top_mem / 1024) \"MB top_cpu=\" top_cpu_name \" \" sprintf(\"%.1f\", top_cpu) \"%\"\n  print msg >> \"/data/adb/y700-proc/proc.log\"\n  close(\"/data/adb/y700-proc/proc.log\")\n}\nBEGIN {\n  nc = ncpu()\n  cpu_pair()\n  base_total = cpu_total\n  base_idle = cpu_idle\n  collect(1)\n  system(\"sleep 1\")\n  cpu_pair()\n  collect(2)\n  emit()\n}\n'\n  if [ -f \"$LOG\" ]; then\n  size=$(\"$BB\" wc -c < \"$LOG\")\n  else\n  size=0\n  fi\n  if [ \"${size:-0}\" -gt 200000 ]; then\n    \"$BB\" tail -c 100000 \"$LOG\" > \"$LOG.tmp\" && mv \"$LOG.tmp\" \"$LOG\"\n  fi\n}\n\nif [ \"${1:-}\" = \"once\" ]; then\n  run_once\nelse\n  while true; do\n    run_once\n    sleep 1\n  done\nfi\n";
    static final String CLEAN = "#!/system/bin/sh\n# 关掉一个普通应用的后台。不碰桌面、系统界面和本应用。\nBB=/data/adb/magisk/busybox\nDIR=/data/adb/y700-proc\nLOG=$DIR/proc.log\npkg=$1\nmkdir -p \"$DIR\"\n\ncase \"$pkg\" in\n  \"\"|*[!a-zA-Z0-9._]*)\n    echo '{\"ok\":false,\"error\":\"bad\"}'\n    exit 1\n    ;;\nesac\ncase \"$pkg\" in\n  com.zui.launcher|com.android.systemui|android|app.y700.proc)\n    echo '{\"ok\":false,\"error\":\"protected\"}'\n    exit 1\n    ;;\nesac\n\nuid=$(pm list packages -U --user 0 | \"$BB\" sed -n \"s/^package:${pkg} uid://p\")\nif [ -z \"$uid\" ] || [ \"$uid\" -lt 10000 ]; then\n  echo '{\"ok\":false,\"error\":\"not_app\"}'\n  exit 1\nfi\n\nbefore=$(awk '/MemAvailable/{print $2; exit}' /proc/meminfo)\nam force-stop --user 0 \"$pkg\"\nsleep 1\nafter=$(awk '/MemAvailable/{print $2; exit}' /proc/meminfo)\nstamp=$(\"$BB\" date '+%Y-%m-%d %H:%M:%S')\necho \"$stamp clean $pkg uid=$uid avail ${before}KB -> ${after}KB\" >> \"$LOG\"\nprintf '{\"ok\":true,\"pkg\":\"%s\",\"before\":%s,\"after\":%s}\\n' \"$pkg\" \"${before:-0}\" \"${after:-0}\"\n";
    private Scripts() {}
}
